// E-Ticaret Sistemi - Ana Giriş Noktası
// Main Entry Point

// Modelleri içe aktar
"src/models/user.hudhud" gunakan;
"src/models/product.hudhud" gunakan;
"src/models/order.hudhud" gunakan;

// Servisleri içe aktar
"src/services/auth.hudhud" gunakan;
"src/services/payment.hudhud" gunakan;
"src/services/notification.hudhud" gunakan;

// Yardımcı kelasları içe aktar
"src/utils/validation.hudhud" gunakan;
"src/utils/formatting.hudhud" gunakan;

cetak("============================================================");
cetak("E-Ticaret Sistemi - Modüler Mimari Demo");
cetak("============================================================\n");

// Servis örnekleri oluştur
var authService = baru AuthService();
var paymentService = baru PaymentService();
var notificationService = baru NotificationService();

cetak("1️⃣  KULLANICI KAYDI");
cetak("─────────────────────────────────────────────────────────\n");

// Yeni gunakanıcı oluştur
var newUser = baru User("Davut Süleyman", "davut@example.com", "güvenli123");
cetak("Kullanıcı oluşturuldu: " + newUser.bilgi());

// Email benarla
jika (Validation.email(newUser.email)) {
    cetak("✓ Email geçerli: " + newUser.email);
} kalau_tidak {
    cetak("✗ Email geçersiz");
}

// Kullanıcıyı kaydet
var authResult = authService.register(newUser);
jika (authResult.success) {
    cetak("✓ " + authResult.message + " (ID: " + authResult.userId + ")");

    // Hoş geldin bildirimi
    notificationService.send(
        newUser.email,
        "Hoş Geldiniz!",
        "Aramıza hoş geldiniz, " + newUser.name
    );
}

cetak("\n2️⃣  ÜRÜN OLUŞTURMA");
cetak("─────────────────────────────────────────────────────────\n");

// Ürün oluştur
var product = baru Product("MacBook Pro M3", 45000, 10, "Elektronik");
cetak("Ürün oluşturuldu: " + product.bilgi());

// Fiyat benarla
jika (Validation.price(product.price)) {
    cetak("✓ Fiyat geçerli: " + Formatting.currency(product.price, "TRY"));
}

// Stok kontrolü
jika (product.inStock()) {
    cetak("✓ Ürün stokta mevcut");
} kalau_tidak {
    cetak("✗ Ürün stokta yok");
}

cetak("\n3️⃣  SİPARİŞ OLUŞTURMA");
cetak("─────────────────────────────────────────────────────────\n");

// Sipariş oluştur
var order = baru Order(
    newUser.id,
    product.id,
    1,
    product.price
);
cetak("Sipariş oluşturuldu: " + order.bilgi());

cetak("\n4️⃣  ÖDEME İŞLEMİ");
cetak("─────────────────────────────────────────────────────────\n");

// Ödeme işle
var paymentResult = paymentService.process(
    order.id,
    order.totalPrice,
    "credit_card"
);

jika (paymentResult.success) {
    cetak("✓ " + paymentResult.message);
    cetak("  İşlem No: " + paymentResult.transactionId);
    cetak("  Tutar: " + Formatting.currency(paymentResult.amount, "TRY"));
    cetak("  Yöntem: " + paymentResult.method);

    // Siparişi onayla
    order.confirm();
    cetak("✓ Sipariş onaylandı: " + order.status);

    // Sipariş onay bildirimi
    notificationService.send(
        newUser.email,
        "Siparişiniz Onaylandı",
        "Sipariş numaranız: " + order.id + " - Toplam: " + Formatting.currency(order.totalPrice, "TRY")
    );
} kalau_tidak {
    cetak("✗ Ödeme başarısız: " + paymentResult.error);
}

cetak("\n============================================================");
cetak("✓ E-Ticaret sistemi demo tamamlandı!");
cetak("✓ Modüler, ölçeklenebilir ve bakımı kolay mimari");
cetak("============================================================");

