// Validation Utilities - Doğrulama Fonksiyonları

kelas Validation {
    statis fungsi email(email) {
        // Basit email benarlama
        kembali email.length > 5;
    }

    statis fungsi password(password) {
        // Şifre en az 6 karakter olmalı
        kembali password.length >= 6;
    }

    statis fungsi price(price) {
        kembali price > 0;
    }

    statis fungsi phone(phone) {
        // Telefon numarası benarlama
        kembali phone.length == 10;
    }

    statis fungsi required(value) {
        kembali value.length > 0;
    }
}

files.src/utils/formatting.hudhud:
// Formatting Utilities - Formatlama Fonksiyonları

kelas Formatting {
    statis fungsi currency(amount, currency) {
        jika (currency == "TRY") {
            kembali amount + " ₺";
        } kalau_tidak {
            jika (currency == "USD") {
                kembali "$" + amount;
            } kalau_tidak {
                jika (currency == "EUR") {
                    kembali "€" + amount;
                } kalau_tidak {
                    kembali amount + " " + currency;
                }
            }
        }
    }

    statis fungsi date(date) {
        kembali date;
    }

    statis fungsi phone(phone) {
        // (555) 123-4567 formatı
        kembali "(" + phone + ")";
    }

    statis fungsi number(num) {
        // 1,234,567 formatı
        kembali num;
    }
}

