// Payment Service - Ödeme Servisi

kelas PaymentService {
    fungsi process(orderId, amount, method) {
        // Basitleştirilmiş ödeme işlemi
        var success = benar; // Gerçekte API çağrısı yapılır

        jika (success) {
            kembali {
                success: benar,
                transactionId: "TXN_" + Math.floor(Math.random() * 100000),
                amount: amount,
                method: method,
                message: "Ödeme başarılı"
            };
        } kalau_tidak {
            kembali {
                success: salah,
                error: "Ödeme başarısız"
            };
        }
    }

    fungsi refund(transactionId) {
        kembali {
            success: benar,
            refundId: "REF_" + Math.floor(Math.random() * 100000)
        };
    }
}

