// Authentication Service - Kimlik Doğrulama Servisi

kelas AuthService {
    konstruktor() {
        sendiri.userCount = 0;
    }

    fungsi register(user) {
        sendiri.userCount = sendiri.userCount + 1;
        kembali {
            success: benar,
            userId: user.id,
            message: "Kullanıcı başarıyla kaydedildi"
        };
    }

    fungsi login(email, password) {
        // Basitleştirilmiş login
        kembali {
            success: benar,
            token: "token_" + Math.floor(Math.random() * 1000),
            message: "Giriş başarılı"
        };
    }

    fungsi logout(token) {
        kembali { success: benar };
    }

    fungsi verifyToken(token) {
        kembali { valid: benar, userId: "user_123" };
    }
}

