// Order Model - Sipariş Modeli

kelas Order {
    konstruktor(userId, productId, quantity, totalPrice) {
        sendiri.id = Math.floor(Math.random() * 10000);
        sendiri.userId = userId;
        sendiri.productId = productId;
        sendiri.quantity = quantity;
        sendiri.totalPrice = totalPrice;
        sendiri.status = "pending";
        sendiri.createdAt = "2024-03-07";
    }

    fungsi bilgi() {
        kembali "Sipariş #" + sendiri.id + " - Kullanıcı: " + sendiri.userId + ", Ürün: " + sendiri.productId + ", Adet: " + sendiri.quantity + ", Toplam: " + sendiri.totalPrice + " TL, Durum: " + sendiri.status;
    }

    fungsi confirm() {
        sendiri.status = "confirmed";
    }

    fungsi getId() {
        kembali sendiri.id;
    }
}

